-- ============================================================================
-- v1402: Seed / sample data — Hypercare registers (v1401) for the demo project
-- ============================================================================
-- Owner request 2026-11-09: sample data where it was missing, 10 records for each Hypercare register,
-- for SEED334-PRJ-08 (fictional "Northbridge Bank" core banking replacement, the same scenario as the
-- Cutover, Operational Readiness, Testing and Data Migration samples).
-- The owner chose simulated hypercare samples (2026-11-09): the logs are dated in the hypercare period
-- (Monday 12 April to Friday 7 May 2027) as if go-live has happened, so every screen shows realistic
-- figures. They sit after today (9 Nov 2026), while the Go-Live registers still show the decisions as
-- pending. The Hypercare Plan is one complete Draft document (one per project).
-- Records: plan 1, command 10, incidents 10, defects 10, performance 10, support 10, exit 10.
-- Vendor-neutral (rule 26), person fields are plain text. display_id is left blank so Admin ID
-- Generation assigns it (rule 16.2). Fixed hex-only ids …-4000-b038- … b03e- (ranges checked free
-- before use). ON CONFLICT (id) DO NOTHING, and nothing is inserted if the project is missing.
-- Calculated values are worked out with the same rules as the app. The final query counts the
-- records per register, so a skipped insert is visible.
-- Prerequisites: v1401. Idempotent.
-- ============================================================================

INSERT INTO public.local_register_records
  (id, register_id, display_id, title, description, status, field_values, account_id, project_id, record_project_id)
SELECT v.id::uuid, v.register_id::uuid, '', v.title, v.description, v.status, v.vals::jsonb, p.account_id, p.id, p.id
FROM (VALUES
  ('00000000-0000-4000-b038-000000000001', '00000000-0000-4000-9001-000000000038', 'Hypercare Plan – Core Banking Release 1', 'How the bank supports staff and customers in the four weeks after the core banking go-live, and when hypercare ends.', 'draft', $j${"document_reference":"HC-PLN-001","document_version":"0.6","document_owner":"Daniel Okafor","next_review_date":"2027-03-26","hypercare_lead":"Ahmed Hassan","hypercare_start":"2027-04-12","hypercare_end":"2027-05-07","purpose":"To give staff and customers fast, visible support after go-live, find and fix problems early, and hand the platform to business-as-usual support once agreed exit criteria are met.","objectives":"Restore full service by Day 1 and keep it stable\nResolve P1 incidents within 4 hours\nClear all critical and high defects before exit\nHand over to business-as-usual support with no open P1 or P2 items","scope":"Core banking platform and its interfaces\nBranches, contact centre, payments and digital channels\nData issues found after migration\nFirst month-end close (April 2027)","out_of_scope":"Release 2 products\nNew change requests (logged for after hypercare)","assumptions":"Vendor support on site for the first two weeks\nSuper users released from normal duties in week 1","constraints":"No non-urgent releases during the first two weeks\nMonth-end close falls in hypercare week 3","support_scope":"Incidents and defects on Release 1\nHow-to questions from staff\nData corrections after migration","support_hours":"24x7","support_tiers":"Tier 0\tBranch super users\tHow-to questions, first checks\nTier 1\tIT service desk\tLogging, triage, known fixes\nTier 2\tHypercare application team\tFaults, data fixes, configuration\nTier 3\tPlatform vendor\tProduct defects","on_call_rota":"Week 1–2\tHypercare lead (night)\tRavi Pillai\tDuty phone\nWeek 1–2\tApplication lead (day)\tMaria Fernandes\tDuty phone\nWeek 3–4\tHypercare lead\tAhmed Hassan\tDuty phone","contact_channels":"Service desk hotline (24x7)\nHypercare channel on the collaboration tool\nFloor walkers at the 10 largest branches in week 1","kpis":"P1 incidents open\t0 at each morning stand-up\tDaily command centre\nCard approval rate\t92% or more\tMonitoring dashboard\nEnd of day finished\tBy 02:00\tBatch monitor\nContact centre service level\t80% in 20 seconds\tTelephony report","monitoring_activities":"Service dashboards watched 24x7 in week 1\nHourly payment queue checks on Day 1 and Day 2\nDaily suspense account review","daily_checks":"End of day completed\t06:00\tBatch operator\nSuspense accounts at zero\t09:00\tFinance control\nOvernight incidents reviewed\t08:30\tHypercare lead\nPayment queues empty\t17:00\tPayments supervisor","severity_definitions":"P1 – critical\tService down for many customers, or money at risk\tPayments not released\nP2 – high\tService degraded or one channel down\tMobile app slow\nP3 – medium\tOne user or a workaround exists\tReport column wrong\nP4 – low\tQuestion or cosmetic issue\tLabel text","response_and_resolution_targets":"P1\t15 minutes\t4 hours\tEvery 30 minutes\nP2\t30 minutes\t8 hours\tEvery 2 hours\nP3\t4 hours\t3 days\tDaily\nP4\t1 day\t10 days\tOn change","escalation_path":"1\tHypercare lead\tP1 raised, or P2 open over 4 hours\n2\tProgramme director\tP1 open over 2 hours\n3\tExecutive sponsor\tCustomer money at risk or regulator involvement","triage_meeting_cadence":"twice_daily","exit_criteria":"No open P1 or P2 incidents\tZero for 5 working days\tIncident register\nNo open critical or high defects\tZero\tDefect register\nFirst month-end closed on time\tClose by working day 3\tFinance sign-off\nSupport handed over\tBusiness-as-usual teams accept\tSupport Model register","handover_to_business_as_usual":"Open P3 and P4 items move to the business-as-usual queue with named owners. The hypercare team stays on call for one more week after exit.","knowledge_transfer":"Batch and end-of-day support\tHypercare application team\tCore banking support team\t2027-04-30\nPayment repairs\tHypercare application team\tPayments support team\t2027-05-03\nKnown errors and workarounds\tHypercare lead\tIT service desk\t2027-05-05","lessons_learned":"To be completed at hypercare exit.","risks_mitigations":"Incident volumes above capacity in week 1\tSlow response, unhappy customers\tExtra service desk and super user cover in week 1\tAhmed Hassan\nMonth-end close delayed\tLate regulatory returns\tMonth-end rehearsal in week 2\tOlivia Banda","roles_and_responsibilities":"Hypercare lead\tRuns the daily command centre and triage\tAhmed Hassan\nProgramme director\tEscalation and exit decision\tDaniel Okafor\nBusiness lead\tBusiness impact and priorities\tAmina Diallo","glossary":"Hypercare\tThe period of heightened support after go-live.\nFloor walker\tAn expert placed in a branch or team to help staff in person.\nBusiness-as-usual\tThe normal, long-term support model.","appendices":"Support Model\tSupport Model register\nIncident priority matrix\tIncident Management register IM-01","version_history":"0.1\t2026-09-30\tAhmed Hassan\tFirst draft\n0.6\t2026-11-06\tAhmed Hassan\tExit criteria agreed with the business","related_documents":"Cutover Strategy\tCUT-STR-001\nCutover Plan\tCUT-PLN-001\nRollback Plan\tRB-PLN-001"}$j$),
